package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func TestSystemdUnitRunsUnprivilegedWithOnlyPiControlDevice(t *testing.T) {
	root := componentDirectory(t)
	content, err := os.ReadFile(filepath.Join(root, "systemd/automation-gateway-led.service"))
	if err != nil {
		t.Fatal(err)
	}
	unit := string(content)
	for _, required := range []string{
		"User=automation-gateway-led",
		"Group=automation-gateway-led",
		"SupplementaryGroups=picontrol",
		"DevicePolicy=closed",
		"DeviceAllow=/dev/piControl0 rw",
		"NoNewPrivileges=yes",
		"ProtectSystem=strict",
		"RestrictAddressFamilies=AF_INET AF_INET6",
	} {
		if !strings.Contains(unit, required) {
			t.Fatalf("unit lacks %q", required)
		}
	}
	for _, forbidden := range []string{"User=root", "PrivateDevices=yes"} {
		if strings.Contains(unit, forbidden) {
			t.Fatalf("unit contains forbidden setting %q", forbidden)
		}
	}
}

func TestInstallerIsSyntacticallyValidAndKeepsClientOptional(t *testing.T) {
	root := componentDirectory(t)
	installer := filepath.Join(root, "install.sh")
	if output, err := exec.Command("bash", "-n", installer).CombinedOutput(); err != nil {
		t.Fatalf("installer syntax: %v\n%s", err, output)
	}
	content, err := os.ReadFile(installer)
	if err != nil {
		t.Fatal(err)
	}
	text := string(content)
	for _, required := range []string{"--binary", "--start", "picontrol", "config.example.yaml", "systemd-analyze verify"} {
		if !strings.Contains(text, required) {
			t.Fatalf("installer lacks %q", required)
		}
	}
	if strings.Contains(text, "enable --now") && !strings.Contains(text, `if [[ "$START" == "true" ]]`) {
		t.Fatal("installer can enable service without explicit --start guard")
	}
}

func componentDirectory(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	return filepath.Dir(file)
}
